+    @Override
+    public void initialize(Properties properties) {
+        Properties actualProperties = properties == null ? new Properties() : properties;
+        storeCreationAllowed = Boolean.parseBoolean(actualProperties.getProperty(
+                ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(actualProperties.getProperty(
+                ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        IntegrityMode integrityMode = integrityMode(actualProperties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
+        configureFileNameStrategy(actualProperties);
+
+        String path = actualProperties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT);
+        storeFolder = new File(path);
+        String lockPath = canonicalPath(storeFolder);
+        storeLock = LOCKS_BY_PATH.computeIfAbsent(lockPath, __ -> new Object());
