+    private void configureFileNameStrategy(Properties properties) {
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
+        if (customFileNameStrategy) {
+            if (configured != null) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return;
+        }
+        if (configured == null || "random".equals(configured)) {
+            ruleViolationFileNameStrategy = __ -> UUID.randomUUID().toString();
+        } else if ("description".equals(configured)) {
+            ruleViolationFileNameStrategy = TextFileBasedViolationStore::descriptionFileName;
+        } else {
+            ruleViolationFileNameStrategy = instantiateStrategy(configured);
+        }
+    }
+
+    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
+        try {
+            Class<?> strategyClass = Class.forName(className);
+            Object strategy = strategyClass.getConstructor().newInstance();
+            if (!(strategy instanceof RuleViolationFileNameStrategy)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s does not implement %s", className, RuleViolationFileNameStrategy.class.getName()));
+            }
+            return (RuleViolationFileNameStrategy) strategy;
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (ClassNotFoundException | InstantiationException | IllegalAccessException | InvocationTargetException |
+                 NoSuchMethodException | SecurityException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot instantiate %s as a %s with a public no-argument constructor",
+                    className, RuleViolationFileNameStrategy.class.getName()), e);
+        }
+    }
+
+    private IntegrityMode integrityMode(String configured) {
+        if ("repair".equals(configured)) {
+            return IntegrityMode.REPAIR;
+        }
+        if ("fail".equals(configured)) {
+            return IntegrityMode.FAIL;
+        }
+        if ("ignore".equals(configured)) {
+            return IntegrityMode.IGNORE;
+        }
+        throw new StoreInitializationFailedException(String.format(
+                "Invalid %s '%s'; accepted values are repair, fail and ignore",
+                INTEGRITY_PROPERTY_NAME, configured));
+    }
+
+    private StoreLocation prepareLocation(boolean failMode) {
+        File index = new File(storeFolder, STORED_RULES_FILE_NAME);
+        boolean indexExists = existsWithoutFollowingLinks(index.toPath());
+        if (!indexExists && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+
+        boolean folderExists = existsWithoutFollowingLinks(storeFolder.toPath());
+        if (folderExists && !storeFolder.isDirectory()) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot use %s as a violation store folder", storeFolder.getAbsolutePath()));
+        }
+        if (indexExists && !isRegularWithoutFollowingLinks(index.toPath())) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Violation store index %s is not a regular file directly in its folder", index.getAbsolutePath()));
+        }
+        if (!folderExists && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot create violation store folder %s", storeFolder.getAbsolutePath()));
+        }
+        // In fail mode, delaying creation is important: a failed check must not create an index.
+        if (failMode && !indexExists) {
+            return new StoreLocation(storeFolder, index);
+        }
+        StoreLocation result = new StoreLocation(storeFolder, index);
+        createLocation(result);
+        return result;
+    }
+
+    private void createLocation(StoreLocation location) {
+        try {
+            if (!location.folder.exists() && !location.folder.mkdirs() && !location.folder.isDirectory()) {
+                throw new IOException("Cannot create folder");
+            }
+            if (!location.folder.isDirectory()) {
+                throw new IOException("Not a directory");
+            }
+            if (!existsWithoutFollowingLinks(location.index.toPath()) && !location.index.createNewFile()) {
+                throw new IOException("Cannot create index");
+            }
+            ensureRegularIndex(location.index);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(
+                    String.format("Cannot create rule store at %s", location.index.getAbsolutePath()), e);
+        }
+    }
+
+    private void ensureRegularIndex(File index) {
+        if (!isRegularWithoutFollowingLinks(index.toPath())) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Violation store index %s is not a regular file directly in its folder", index.getAbsolutePath()));
+        }
+    }
+
+    private Properties loadProperties(File file) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(file)) {
+            result.load(inputStream);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        return result;
+    }
+
+    private void failIfBroken(IntegrityAnalysis analysis) {
+        if (!analysis.hasProblems()) {
+            return;
+        }
+        StringBuilder message = new StringBuilder();
+        message.append("Violation store integrity check failed (default.allowStoreUpdate=")
+                .append(storeUpdateAllowed).append("): ");
+        appendEntries(message, "broken", analysis.brokenEntries);
+        appendEntries(message, "resolved", analysis.resolvedEntries);
+        appendEntries(message, "shared", analysis.sharedEntries);
+        appendEntries(message, "misplaced/colliding/occupied", analysis.otherEntries);
+        if (!analysis.unownedFiles.isEmpty()) {
+            message.append("unowned files ").append(analysis.unownedFiles);
+        }
+        throw new StoreInitializationFailedException(message.toString());
+    }
+
+    private void appendEntries(StringBuilder message, String condition, List<Entry> entries) {
+        if (entries.isEmpty()) {
+            return;
+        }
+        if (message.charAt(message.length() - 1) != ' ') {
+            message.append("; ");
+        }
+        message.append(condition).append(" entries ");
+        List<Entry> sorted = new ArrayList<>(entries);
+        Collections.sort(sorted, Comparator.comparing(entry -> entry.description));
+        message.append('[');
+        for (int i = 0; i < sorted.size(); i++) {
+            if (i > 0) {
+                message.append(", ");
+            }
+            Entry entry = sorted.get(i);
+            message.append("'").append(entry.description).append("' -> '").append(entry.name).append("'");
+        }
+        message.append(']');
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storeLock()) {
+            return properties().containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        synchronized (storeLock()) {
+            requireInitialized();
+            log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+            if (!storeUpdateAllowed) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+            }
+
+            String description = rule.getDescription();
+            Properties current = properties();
+            String existingName = current.getProperty(description);
+            if (existingName == null && violations.isEmpty()) {
+                return;
+            }
+
+            String fileName = existingName == null ? requiredFileName(description) : existingName;
+            PathInfo pathInfo = analyzePath(fileName, storeState.location);
+            validateSavePath(fileName, pathInfo, existingName != null);
+
+            if (violations.isEmpty() && existingName != null && integrityModeForSave() == IntegrityMode.REPAIR) {
+                forgetEmptyRule(description, fileName, pathInfo, current);
+                return;
+            }
+
+            byte[] contents = encodeViolations(violations);
+            boolean hadTarget = pathInfo.exists;
+            byte[] previous = hadTarget && pathInfo.resolved ? readBytes(pathInfo.rawPath) : null;
+            try {
+                Files.write(pathInfo.rawPath, contents);
+                if (existingName == null) {
+                    current.setProperty(description, fileName);
+                    persist(current);
+                }
+            } catch (IOException | RuntimeException e) {
+                if (existingName == null) {
+                    current.remove(description);
+                    if (!hadTarget) {
+                        deleteCreatedTarget(pathInfo);
+                    } else if (previous != null) {
+                        restore(pathInfo.rawPath, previous);
+                    }
+                } else if (previous != null) {
+                    restore(pathInfo.rawPath, previous);
+                }
+                if (e instanceof StoreUpdateFailedException) {
+                    throw (StoreUpdateFailedException) e;
+                }
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+    }
+
+    private void forgetEmptyRule(String description, String fileName, PathInfo pathInfo, Properties current) {
+        Entry removed = new Entry(description, fileName);
+        List<Entry> entries = entries(current);
+        boolean shared = isShared(removed, entries, pathInfo);
+        if (!shared && pathInfo.resolved) {
+            try {
+                deleteNamedFile(pathInfo);
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        current.remove(description);
+        try {
+            persist(current);
+        } catch (RuntimeException e) {
+            current.setProperty(description, fileName);
+            throw e;
+        }
+    }
+
+    private boolean isShared(Entry entry, List<Entry> allEntries, PathInfo ownPath) {
+        FileIdentity identity = ownPath.identity;
+        for (Entry other : allEntries) {
+            if (other.description.equals(entry.description)) {
+                continue;
+            }
+            if (other.name.equals(entry.name)) {
+                return true;
+            }
+            if (identity != null && identity.equals(analyzePath(other.name, storeState.location).identity)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private String requiredFileName(String description) {
+        String result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (result == null || result.isEmpty()) {
+            throw new StoreUpdateFailedException("RuleViolationFileNameStrategy returned no file name for rule '" + description + "'");
+        }
+        return result;
+    }
+
+    private void validateSavePath(String fileName, PathInfo pathInfo, boolean knownRule) {
+        if (!pathInfo.valid || !pathInfo.directTargetLocation || pathInfo.isIndex) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Rule violation file name '%s' does not lead to a regular file directly in the store folder", fileName));
+        }
+        if (pathInfo.exists && !pathInfo.resolved) {
+            boolean danglingLink = Files.isSymbolicLink(pathInfo.rawPath) && !pathInfo.targetExists;
+            if (!danglingLink) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Rule violation file name '%s' does not lead to a regular file directly in the store folder", fileName));
+            }
+        }
+        if (!knownRule && pathInfo.exists) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Rule violation file name '%s' names something not recorded by its own entry", fileName));
+        }
+    }
+
+    private byte[] encodeViolations(List<String> violations) {
+        StringBuilder result = new StringBuilder();
+        for (String violation : violations) {
+            result.append(escape(violation)).append('\n');
+        }
+        return result.toString().getBytes(UTF_8);
+    }
+
+    private String escape(String value) {
+        StringBuilder result = new StringBuilder(value.length());
+        for (int i = 0; i < value.length(); i++) {
+            char character = value.charAt(i);
+            if (character == '\\') {
+                result.append("\\\\");
+            } else if (character == '\r') {
+                result.append("\\\r");
+            } else if (character == '\n') {
+                result.append("\\\n");
+            } else {
+                result.append(character);
+            }
+        }
+        return result.toString();
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storeLock()) {
+            requireInitialized();
+            String fileName = properties().getProperty(rule.getDescription());
+            checkArgument(fileName != null, "No rule stored with description '%s'", rule.getDescription());
+            return readLines(fileName);
+        }
+    }
+
+    private List<String> readLines(String fileName) {
+        try {
+            return parseViolations(Files.readAllBytes(analyzePath(fileName, storeState.location).rawPath));
+        } catch (IOException | RuntimeException e) {
+            if (e instanceof StoreReadException) {
+                throw (StoreReadException) e;
+            }
+            throw new StoreReadException(e);
+        }
+    }
+
+    private List<String> parseViolations(byte[] bytes) {
+        String text = new String(bytes, UTF_8);
+        List<String> result = new ArrayList<>();
+        StringBuilder current = new StringBuilder();
+        for (int i = 0; i < text.length(); i++) {
+            char character = text.charAt(i);
+            if (character == '\\' && i + 1 < text.length()) {
+                char next = text.charAt(i + 1);
+                if (next == '\\') {
+                    current.append('\\');
+                    i++;
+                } else if (next == '\r') {
+                    current.append('\r');
+                    i++;
+                } else if (next == '\n') {
+                    current.append('\n');
+                    i++;
+                } else {
+                    current.append(character);
+                }
+            } else if (character == '\r' || character == '\n') {
+                if (character == '\r' && i + 1 < text.length() && text.charAt(i + 1) == '\n') {
+                    i++;
+                }
+                if (current.length() > 0) {
+                    result.add(current.toString());
+                    current.setLength(0);
+                }
+            } else {
+                current.append(character);
+            }
+        }
+        if (current.length() > 0) {
+            result.add(current.toString());
+        }
+        return result;
+    }
+
+    private void repair(IntegrityAnalysis analysis) {
+        boolean indexChanged = false;
+        for (Entry entry : analysis.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken || entry.resolved) {
+                analysis.properties.remove(entry.description);
+                indexChanged = true;
+                if (entry.resolved) {
+                    try {
+                        deleteNamedFile(entry.path);
+                    } catch (IOException e) {
+                        throw new StoreInitializationFailedException(e);
+                    }
