+            char character = value.charAt(i);
+            if (character == '\\') {
+                result.append("\\\\");
+            } else if (character == '\r') {
+                result.append("\\\r");
+            } else if (character == '\n') {
+                result.append("\\\n");
+            } else {
+                result.append(character);
+            }
+        }
+        return result.toString();
+    }
